"use client";
import { useState } from "react";
import { useRouter } from "next/navigation";
import { userFeedback } from "@/lib/user-feedback";
import { Button } from "@/components/ui/button";
import buttonStyles from "@/components/action-button.module.css";
import { DeleteConfirmDialog } from "@/components/ui/delete-confirm-dialog";
export function DeleteOrderButton({ orderId, returnToOrders = false }: { orderId: string; returnToOrders?: boolean }) { const [confirming, setConfirming] = useState(false); const [message, setMessage] = useState(""); const [busy, setBusy] = useState(false); const router = useRouter(); async function remove() { if (busy) return; setBusy(true); setMessage(""); try { const response = await fetch(`/api/orders/${orderId}`, { method: "DELETE" }); if (response.ok) { if (returnToOrders) router.push("/orders"); else router.refresh(); return; } const result = await response.json().catch(() => null) as { error?: string } | null; setMessage(result?.error || `删除失败（HTTP ${response.status}），请稍后重试。`); } catch { setMessage(userFeedback.network); } finally { setBusy(false); } } return <><Button type="button" variant="danger" className={buttonStyles.statusAction} onClick={() => setConfirming(true)}>删除 SO</Button>{confirming && <DeleteConfirmDialog title="确认删除此 SO？" message={message} busy={busy} onClose={() => setConfirming(false)} onConfirm={remove}><p>将删除该订单及其上传文件。若已有后续业务记录，系统会阻止删除。</p></DeleteConfirmDialog>}</>; }
